import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { BLOG_POSTS } from './blogPosts'

// public/sitemap.xml is generated by scripts/generate-sitemap.mjs (runs before
// every build). This guards against a committed sitemap that has drifted.
const xml = readFileSync(new URL('../../public/sitemap.xml', import.meta.url), 'utf8')
const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map(m => m[1])

describe('sitemap.xml', () => {
  it('lists every blog post', () => {
    for (const p of BLOG_POSTS) {
      expect(locs).toContain(`https://www.scorifygolf.com/blog/${p.slug}`)
    }
  })

  it('only uses final https://www. URLs', () => {
    for (const loc of locs) expect(loc.startsWith('https://www.scorifygolf.com/')).toBe(true)
  })

  it('does not list pages blocked in robots.txt', () => {
    for (const blocked of ['/login', '/home', '/admin', '/wager/']) {
      expect(locs.some(l => l.includes(blocked))).toBe(false)
    }
  })
})
